import re, pandas as pd, numpy as np
els=['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
df=pd.read_csv('b3_supercon_data.csv')
pat=re.compile(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)')
def parse(s):
 d={}
 for e,n in pat.findall(s): d[e]=d.get(e,0)+(float(n) if n else 1.)
 z=sum(d.values())
 return d,{e:d.get(e,0)/z for e in els},z
print('Top compositions normalized on all atoms:')
for _,r in df.nlargest(60,'target').iterrows():
 d,x,z=parse(r.composition)
 selected={e:round(v,6) for e,v in x.items() if v}
 print(f"{r.target:6.1f}  {r.composition:36s} sum_selected={sum(x.values()):.4f} {selected}")
