for _,r in df.iterrows():
 d={}
 for e,n in pat.findall(r.composition):d[e]=d.get(e,0)+(float(n) if n else 1)
 z=sum(d.values()); frac={e:n/z for e,n in d.items()}
 only=set(d)<=set(E); inside=all(frac.get(e,0)<=bounds[e]+1e-9 for e in E)
