import re,pandas as pd,numpy as np
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,HistGradientBoostingRegressor,GradientBoostingRegressor
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.neighbors import KNeighborsRegressor
from scipy.optimize import differential_evolution
E=['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
hi=np.array([.697674,.454545,.333333,.285714,.4,.272727,.78,.521978,.502513,.98,.972,.265043,.5,1,.5,.28,1,.9918,1,.6])
df=pd.read_csv('b3_supercon_data.csv');pat=re.compile(r'([A-Z][a-z]?)([0-9]*\.?[0-9]*)');X=[]
for s in df.composition:
 d={}
 for e,n in pat.findall(s):d[e]=d.get(e,0)+(float(n) if n else 1.)
 z=sum(d.values());X.append([d.get(e,0)/z for e in E])
X=np.array(X); y=df.target.values
mods=[ExtraTreesRegressor(n_estimators=800,min_samples_leaf=2,max_features=.9,n_jobs=-1,random_state=1),RandomForestRegressor(n_estimators=800,min_samples_leaf=2,max_features=.9,n_jobs=-1,random_state=2),GradientBoostingRegressor(n_estimators=200,max_depth=2,min_samples_leaf=3,loss='huber',random_state=3),HistGradientBoostingRegressor(max_iter=200,l2_regularization=5,max_leaf_nodes=15,min_samples_leaf=10,random_state=4),make_pipeline(StandardScaler(),KNeighborsRegressor(n_neighbors=10,weights='distance',p=1))]
for m in mods:m.fit(X,y)
def preds(x):return np.array([m.predict(np.asarray(x).reshape(1,-1))[0] for m in mods])
def obj(x):
 p=preds(x)
 return -(p[:4].mean()*.75+p[4]*.25)
res=differential_evolution(obj,list(zip(np.zeros(20),hi)),seed=12,popsize=20,maxiter=300,tol=1e-8,polish=False,workers=1,updating='immediate')
# snap entries below min positive values to zero and coordinate search over observed feature values
x=res.x.copy()
for j in range(20):
 pos=X[:,j][X[:,j]>0]
 if len(pos) and x[j]<pos.min()/2:x[j]=0
# greedy coordinate choose among 0, observed levels, bounds (repeat)
for repeat in range(4):
 for j in range(20):
  vals=np.unique(np.r_[0,X[:,j],hi[j]])
  vals=vals[vals<=hi[j]+1e-12]
  scores=[]
  for v in vals:
   q=x.copy();q[j]=v;scores.append(obj(q))
  x[j]=vals[np.argmin(scores)]
print('DE objective',-res.fun,'preds',preds(res.x),'sum',res.x.sum())
print(', '.join(f'{e}={v:.9g}' for e,v in zip(E,res.x)))
print('\nSnapped/coordinate objective',-obj(x),'preds',preds(x),'sum',x.sum())
print(', '.join(f'{e}={v:.9g}' for e,v in zip(E,x)))
# selected reference candidates
refs={}
for idx,r in df.iterrows():
 if r.target>=90:
  refs[r.composition]=X[idx]
refs['Ba2Ca2Cu3O normalized Hg-ratio']=np.array([8/15,3/15,2/15,0,0,2/15]+[0]*14)
print('\nReferences predictions:')
for name,v in refs.items():
 if np.all(v<=hi+1e-8): print(f'{name:38} actual={df.loc[df.composition==name,"target"].max() if name in set(df.composition) else np.nan:6.1f} sum={v.sum():.3f} pred={preds(v).round(1)} ens={-obj(v):.1f}')
